import React, { useEffect, useState } from 'react';
import { createClaim } from '../services/api';

export default function NewClaimCreate({ onCreated, onCancel }) {
  const [serial, setSerial] = useState('');
  const [component_failure, setComponent] = useState('');
  const [serviceCompanies, setServiceCompanies] = useState([]); // [{ id, name }]
  const [selectedServiceCompanyId, setSelectedServiceCompanyId] = useState('');
  const [date_failure, setDateFailure] = useState()
  const [claim_operating_time, setOperatingTime] = useState('')
  const [description_failure, setDescripFail] = useState('')
  const [recovery_method, setRecMethod] = useState('')
  const [model, setModel] = useState('')
  const [spare_parts, setSpareParts] = useState('')
  const [date_recovery, setDateRec] = useState()
  const [equipment_downtime, setDowmtime] =useState('')
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetch('/api/service_companies/')
      .then(res => res.json())
      .then(data => setServiceCompanies(Array.isArray(data) ? data : []))
      .catch(() => setServiceCompanies([]));    
          
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    const payload = {
      serial_number_machine: serial,
      model_machine: model,
      service_company: selectedServiceCompanyId || null,
      component_failure: component_failure,
      date_failure: date_failure,
      claim_operating_time: claim_operating_time,
      description_failure: description_failure,
      recovery_method: recovery_method,
      spare_parts: spare_parts,
      date_recovery: date_recovery,
      equipment_downtime: equipment_downtime,
    };
    try {
      const res = await createClaim(payload);
      setLoading(false);
      onCreated?.(res);
    } catch (err) {
      setLoading(false);
      setError(err?.message || 'Ошибка при создании');
    }
  };

  return (
    <div className="new-machine-create" style={{ border: '1px solid #ccc', padding: 16, borderRadius: 6, margin: '12px 0' }}>
      <h3>Создать новоую Рекламацию</h3>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <input placeholder="Серийный номер" value={serial} onChange={(e) => setSerial(e.target.value)} required />
        <input placeholder="Модель машины" value={model} onChange={(e) => setModel(e.target.value)} required />
        <input placeholder="Узел отказа" value={component_failure} onChange={(e) => setComponent(e.target.value)} required />
        <input placeholder="Дата отказа" value={date_failure} onChange={(e) => setDateFailure(e.target.value)} required />
        <input placeholder="Наработка в момент обращения" value={claim_operating_time} onChange={(e) => setOperatingTime(e.target.value)} required />
        <input placeholder="Описание отказа" value={description_failure} onChange={(e) => setDescripFail(e.target.value)} required />

        <select value={selectedServiceCompanyId} onChange={(e) => setSelectedServiceCompanyId(e.target.value)}>
          <option value="">Выберите сервисную компанию</option>
          {serviceCompanies.map((s) => (
            <option key={s.id} value={s.id}>{s.name}</option>
          ))}
        </select>

        <input placeholder="Запасные части" value={spare_parts} onChange={(e) => setSpareParts(e.target.value)} required />
        <input placeholder="Дата восстановления" value={date_recovery} onChange={(e) => setDateRec(e.target.value)} required />
        <input placeholder="Метод восстановления" value={recovery_method} onChange={(e) => setRecMethod(e.target.value)} required />
        <input placeholder="Время простоя (дни)" value={equipment_downtime} onChange={(e) => setDowmtime(e.target.value)} required />
          

        <div style={{ display: 'flex', gap: 8 }}>
          <button type="submit" disabled={loading}>{loading ? 'Создание...' : 'Создать'}</button>
          <button type="button" onClick={onCancel} disabled={loading}>Отмена</button>
        </div>
        {error && <div style={{ color: 'red' }}>{error}</div>}
      </form>
    </div>
  );
}
